247	    @Override
248	    @Transactional
249	    public void saveOwner(Owner owner) throws DataAccessException {
250	        boolean isNew = owner.isNew();
251	        // Resolve the effective registration date (supplied, or defaulted to the server date) and
252	        // roll it forward to the next business day so it never lands on a weekend. Everything
253	        // derived from the registration date below must use this adjusted value.
254	        LocalDate registrationDate = toBusinessDay(
255	            owner.getRegistrationDate() != null ? owner.getRegistrationDate() : LocalDate.now());
256	        owner.setRegistrationDate(registrationDate);
257	        if (owner.isNew()) {
258	            // Resolve the household first so the owner's householdId is part of its identityKey. The
259	            // members are existing owners with the same last name and address; joining them makes this
260	            // owner share their stable householdId (back-filled onto any member still missing it).
261	            List<Owner> householdMembers = findHouseholdMembers(owner);
262	            if (!householdMembers.isEmpty()) {
263	                owner.setHouseholdId(resolveHouseholdId(householdMembers));
264	            }
265	            // Size of the household after this create: the existing members plus this new owner.
266	            owner.setHouseholdMemberCount(householdMembers.size() + 1);
267	        }
268	        // Single consolidated duplicate check: reject only when the new owner's WHOLE identityKey
269	        // (normalizedTelephone | email-or-empty | householdId) equals an existing owner's. This
270	        // subsumes the former separate telephone, email and household checks.
271	        if (owner.isNew() && isIdentityKeyAlreadyUsed(owner)) {
272	            throw new DuplicateIdentityException(owner.getIdentityKey());
273	        }
274	        if (owner.isNew()
275	            && countOwnersInCity(owner) >= CityOwnerLimitExceededException.MAX_OWNERS_PER_CITY) {
276	            throw new CityOwnerLimitExceededException(owner.getCity());
277	        }
278	        if (owner.isNew()
279	            && countOwnersRegisteredOn(registrationDate) >= DailyOwnerLimitExceededException.MAX_OWNERS_PER_DAY) {
280	            throw new DailyOwnerLimitExceededException(registrationDate);
281	        }
282	        if (owner.isNew() && owner.getCustomerCode() == null) {
283	            owner.setCustomerCode(generateCustomerCode(owner));
284	        }
285	        if (owner.isNew()) {
286	            owner.setNamesakeCount(countNamesakes(owner));
287	            owner.setBulkSignupWarning(
288	                countOwnersRegisteredOn(registrationDate) > BULK_SIGNUP_WARNING_THRESHOLD);
289	        }
290	        if (owner.getMembershipNumber() == null) {
291	            owner.setMembershipNumber(generateMembershipNumber(owner));
292	        }
293	        ownerRepository.save(owner);
294	        if (isNew) {
295	            AUDIT.info("owner created id={} customerCode={} membershipLevel={} registrationDate={}",
296	                owner.getId(), owner.getCustomerCode(), owner.getMembershipLevel(),
297	                owner.getRegistrationDate());
298	        }
299	    }
300	
301	    /**
302	     * Report whether {@code owner}'s derived {@code identityKey} is already used by any existing
303	     * owner. The key consolidates telephone, email and household into one value, so two owners
304	     * collide only when their whole key is equal (see {@link Owner#getIdentityKey()}). By this point
305	     * the owner's {@code householdId} has been resolved, so its key is complete.
306	     */
307	    private boolean isIdentityKeyAlreadyUsed(Owner owner) {
308	        String identityKey = owner.getIdentityKey();
309	        return ownerRepository.findAll().stream()
310	            .anyMatch(existing -> identityKey.equals(existing.getIdentityKey()));
311	    }
312	
313	    /**
314	     * Count the owners that already exist (before this create) sharing the same first name and last
315	     * name as {@code owner}, compared case-insensitively. Returns zero when the owner's name is
316	     * unique among the existing owners.
317	     */
318	    private int countNamesakes(Owner owner) {
319	        String firstName = owner.getFirstName();
320	        String lastName = owner.getLastName();
321	        if (firstName == null || lastName == null) {
322	            return 0;
323	        }
324	        return (int) ownerRepository.findAll().stream()
325	            .filter(existing -> firstName.equalsIgnoreCase(existing.getFirstName())
326	                && lastName.equalsIgnoreCase(existing.getLastName()))
327	            .count();
328	    }
329	
330	    /**
331	     * Find the owners that already belong to the same household as {@code owner}, i.e. have the same
332	     * last name and the same address. Last names are compared case-insensitively with collapsed
333	     * whitespace; addresses are compared in their canonical normalized form (see
334	     * {@link AddressNormalizer}), so differences in letter case, runs of spaces or street-type
335	     * abbreviations are ignored. Returns an empty list when the owner has no last name or address to
336	     * match on.
337	     */
338	    private List<Owner> findHouseholdMembers(Owner owner) {
339	        String lastName = normalizeHouseholdKey(owner.getLastName());
340	        String address = AddressNormalizer.normalize(owner.getAddress());
341	        if (lastName == null || address == null) {
342	            return List.of();
343	        }
344	        return ownerRepository.findAll().stream()
345	            .filter(existing -> lastName.equals(normalizeHouseholdKey(existing.getLastName()))
346	                && address.equals(AddressNormalizer.normalize(existing.getAddress())))
347	            .toList();
348	    }
349	
350	    /**
351	     * Resolve the stable {@code householdId} shared by a household. If any existing member already
352	     * carries one it is reused so the identifier stays stable as further owners join; otherwise a
353	     * new one is generated. The resolved value is back-filled onto every member that is missing it
354	     * (or has a different one) so all members of the household share the same identifier.
355	     */
356	    private String resolveHouseholdId(List<Owner> members) {
357	        String householdId = members.stream()
358	            .map(Owner::getHouseholdId)
359	            .filter(id -> id != null && !id.isBlank())
360	            .findFirst()
361	            .orElseGet(() -> UUID.randomUUID().toString());
362	        for (Owner member : members) {
363	            if (!householdId.equals(member.getHouseholdId())) {
364	                member.setHouseholdId(householdId);
365	                ownerRepository.save(member);
366	            }
367	        }
368	        return householdId;
369	    }
370	
371	    /**
372	     * Normalize a value for case-insensitive, whitespace-insensitive household comparison by
373	     * trimming, collapsing internal runs of whitespace to a single space and lower-casing it.
374	     */
375	    private String normalizeHouseholdKey(String value) {
376	        return value == null ? null : value.trim().replaceAll("\\s+", " ").toLowerCase();
377	    }
378	
379	    /**
380	     * Build an owner's {@code customerCode} as {@code '<CITY3>-<LAST3>-<NNNN>'}: CITY3 is the
381	     * upper-cased first three letters of the owner's city, LAST3 the upper-cased first three
382	     * letters of the owner's last name, and NNNN a per-city 4-digit zero-padded sequence equal
383	     * to one more than the number of owners already in that city (e.g. {@code 'LON-SMI-0007'}).
384	     */
385	    private String generateCustomerCode(Owner owner) {
386	        String city3 = upperPrefix3(owner.getCity());
387	        String last3 = upperPrefix3(owner.getLastName());
388	        long sequence = countOwnersInCity(owner) + 1L;
389	        return String.format("%s-%s-%04d", city3, last3, sequence);
390	    }
391	
392	    /**
393	     * Return the upper-cased first three letters of {@code value} (or fewer when it is shorter),
394	     * the shared truncate-and-upper idiom used for each {@code customerCode} prefix segment.
395	     */
396	    private String upperPrefix3(String value) {
397	        return value.substring(0, Math.min(3, value.length())).toUpperCase();
398	    }
399	
400	    /**
401	     * Count the owners that already exist (before this create) in the same city as {@code owner},
402	     * compared case-insensitively.
403	     */
404	    private long countOwnersInCity(Owner owner) {
405	        String city = owner.getCity();
406	        return ownerRepository.findAll().stream()
407	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
408	            .count();
409	    }
410	
411	    /**
412	     * Count the owners that already exist (before this create) whose {@code registrationDate} falls
413	     * on the given {@code date}. Used to enforce the per-day create cap.
414	     */
415	    private long countOwnersRegisteredOn(LocalDate date) {
416	        return ownerRepository.findAll().stream()
417	            .filter(existing -> date.equals(existing.getRegistrationDate()))
418	            .count();
419	    }
420	
421	    /**
422	     * Roll {@code date} forward to the next business day when it falls on a weekend: a Saturday or
423	     * Sunday becomes the following Monday, while a weekday is returned unchanged. Registration dates
424	     * are required to fall on a business day.
425	     */
426	    private LocalDate toBusinessDay(LocalDate date) {
427	        switch (date.getDayOfWeek()) {
428	            case SATURDAY:
429	                return date.plusDays(2);
430	            case SUNDAY:
431	                return date.plusDays(1);
432	            default:
433	                return date;
434	        }
435	    }
436	
437	    /**
438	     * Build an owner's {@code membershipNumber} as {@code '<customerCode>-M<YY>'}, where YY is the
439	     * last two digits of the owner's {@code registrationDate} year (e.g. {@code 'SMI-0007-M26'}).
440	     */
441	    private String generateMembershipNumber(Owner owner) {
442	        String yy = String.format("%02d", owner.getRegistrationDate().getYear() % 100);
443	        return String.format("%s-M%s", owner.getCustomerCode(), yy);
444	    }
445	
446	    @Override
447	    @Transactional(readOnly = true)
448	    public Collection<Owner> findOwnerByLastName(String lastName) throws DataAccessException {
449	        return ownerRepository.findByLastName(lastName);
450	    }
451	
452	    @Override
453	    @Transactional(readOnly = true)
454	    public Collection<Visit> findVisitsByPetId(int petId) {
455	        return visitRepository.findByPetId(petId);
456	    }
457	
458	    @Override
459	    @Transactional(readOnly = true)
460	    public List<Specialty> findSpecialtiesByNameIn(Set<String> names) {
461	        return findEntityById(() -> specialtyRepository.findSpecialtiesByNameIn(names));
462	    }
463	
464	    private <T> T findEntityById(Supplier<T> supplier) {
465	        try {
466	            return supplier.get();
467	        } catch (ObjectRetrievalFailureException | EmptyResultDataAccessException e) {
468	            // Just ignore not found exceptions for Jdbc/Jpa realization
469	            return null;
470	        }
471	    }
472	
473	}
