36	@Entity
37	@Table(name = "owners")
38	public class Owner extends Person {
39	    @Column(name = "address")
40	    @NotEmpty
41	    private String address;
42	
43	    @Column(name = "city")
44	    @NotEmpty
45	    private String city;
46	
47	    @Column(name = "postcode")
48	    private String postcode;
49	
50	    @Column(name = "telephone")
51	    @NotEmpty
52	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form: a '+' followed by 8 to 15 digits")
53	    private String telephone;
54	
55	    @Column(name = "email")
56	    @Email
57	    private String email;
58	
59	    @Column(name = "registration_date", columnDefinition = "DATE")
60	    private LocalDate registrationDate;
61	
62	    @Column(name = "customer_code")
63	    private String customerCode;
64	
65	    @Column(name = "membership_number")
66	    private String membershipNumber;
67	
68	    @Column(name = "household_id")
69	    private String householdId;
70	
71	    @Column(name = "namesake_count")
72	    private Integer namesakeCount;
73	
74	    @Column(name = "bulk_signup_warning")
75	    private boolean bulkSignupWarning;
76	
77	    @Column(name = "household_member_count")
78	    private Integer householdMemberCount;
79	
80	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
81	    private Set<Pet> pets;
82	
83	    /**
84	     * Transient, write-only request flag: when {@code true}, creating this owner is allowed even if
85	     * another owner already shares the same last name and address. Never persisted or returned.
86	     */
87	    @Transient
88	    private boolean sharesHousehold;
89	
90	    public String getAddress() {
91	        return this.address;
92	    }
93	
94	    public void setAddress(String address) {
95	        this.address = address;
96	    }
97	
98	    public String getCity() {
99	        return this.city;
100	    }
101	
102	    public void setCity(String city) {
103	        this.city = city;
104	    }
105	
106	    public String getPostcode() {
107	        return this.postcode;
108	    }
109	
110	    public void setPostcode(String postcode) {
111	        this.postcode = postcode;
112	    }
113	
114	    public String getTelephone() {
115	        return this.telephone;
116	    }
117	
118	    public void setTelephone(String telephone) {
119	        this.telephone = telephone;
120	    }
121	
122	    public String getEmail() {
123	        return this.email;
124	    }
125	
126	    public void setEmail(String email) {
127	        this.email = email;
128	    }
129	
130	    public LocalDate getRegistrationDate() {
131	        return this.registrationDate;
132	    }
133	
134	    public void setRegistrationDate(LocalDate registrationDate) {
135	        this.registrationDate = registrationDate;
136	    }
137	
138	    public String getCustomerCode() {
139	        return this.customerCode;
140	    }
141	
142	    public void setCustomerCode(String customerCode) {
143	        this.customerCode = customerCode;
144	    }
145	
146	    public String getMembershipNumber() {
147	        return this.membershipNumber;
148	    }
149	
150	    public void setMembershipNumber(String membershipNumber) {
151	        this.membershipNumber = membershipNumber;
152	    }
153	
154	    public String getHouseholdId() {
155	        return this.householdId;
156	    }
157	
158	    public void setHouseholdId(String householdId) {
159	        this.householdId = householdId;
160	    }
161	
162	    public Integer getNamesakeCount() {
163	        return this.namesakeCount;
164	    }
165	
166	    public void setNamesakeCount(Integer namesakeCount) {
167	        this.namesakeCount = namesakeCount;
168	    }
169	
170	    /**
171	     * Derive the owner's numeric {@code membershipLevel}, from 1 to 3, assigned at creation: it
172	     * starts at 1, gains 1 when an email is present, gains 1 when the owner's name was unique at
173	     * creation time ({@code namesakeCount} is 0), and is capped at 3. Level 4 is reserved for tenure.
174	     */
175	    @Transient
176	    public Integer getMembershipLevel() {
177	        int level = 1;
178	        if (this.email != null && !this.email.isBlank()) {
179	            level++;
180	        }
181	        if (Integer.valueOf(0).equals(this.namesakeCount)) {
182	            level++;
183	        }
184	        return Math.min(level, 3);
185	    }
186	
187	    /**
188	     * Derive the owner's read-only {@code checkDigit}: a single Luhn check digit (0-9) computed
189	     * over the digits contained in the owner's {@code customerCode}. Non-digit characters (the
190	     * '-' separators and letters) are ignored. Returns {@code null} when no {@code customerCode}
191	     * has been assigned yet.
192	     */
193	    @Transient
194	    public Integer getCheckDigit() {
195	        if (this.customerCode == null) {
196	            return null;
197	        }
198	        int sum = 0;
199	        boolean dbl = true;
200	        for (int i = this.customerCode.length() - 1; i >= 0; i--) {
201	            char c = this.customerCode.charAt(i);
202	            if (c < '0' || c > '9') {
203	                continue;
204	            }
205	            int d = c - '0';
206	            if (dbl) {
207	                d *= 2;
208	                if (d > 9) {
209	                    d -= 9;
210	                }
211	            }
212	            sum += d;
213	            dbl = !dbl;
214	        }
215	        return (10 - (sum % 10)) % 10;
216	    }
217	
218	    /**
219	     * Derive the owner's {@code identityKey}, the single value used to detect duplicate owners:
220	     * {@code normalizedTelephone + '|' + (email or empty) + '|' + householdId}. The telephone and
221	     * email are already stored in their canonical (E.164 / lower-cased) form, so a {@code null} or
222	     * blank email contributes an empty segment and an absent {@code householdId} an empty segment.
223	     * Two owners are duplicates only when their whole {@code identityKey} is equal.
224	     */
225	    @Transient
226	    public String getIdentityKey() {
227	        String telephonePart = this.telephone == null ? "" : this.telephone;
228	        String emailPart = (this.email == null || this.email.isBlank()) ? "" : this.email;
229	        String householdPart = this.householdId == null ? "" : this.householdId;
230	        return telephonePart + "|" + emailPart + "|" + householdPart;
231	    }
232	
233	    public boolean isBulkSignupWarning() {
234	        return this.bulkSignupWarning;
235	    }
236	
237	    public void setBulkSignupWarning(boolean bulkSignupWarning) {
238	        this.bulkSignupWarning = bulkSignupWarning;
239	    }
240	
241	    public Integer getHouseholdMemberCount() {
242	        return this.householdMemberCount;
243	    }
244	
245	    public void setHouseholdMemberCount(Integer householdMemberCount) {
246	        this.householdMemberCount = householdMemberCount;
247	    }
248	
249	    public boolean isSharesHousehold() {
250	        return this.sharesHousehold;
251	    }
252	
253	    public void setSharesHousehold(boolean sharesHousehold) {
254	        this.sharesHousehold = sharesHousehold;
255	    }
256	
257	    protected Set<Pet> getPetsInternal() {
258	        if (this.pets == null) {
259	            this.pets = new HashSet<>();
260	        }
261	        return this.pets;
262	    }
263	
264	    protected void setPetsInternal(Set<Pet> pets) {
265	        this.pets = pets;
266	    }
267	
268	    public List<Pet> getPets() {
269	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
270	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
271	        return Collections.unmodifiableList(sortedPets);
272	    }
273	
274	    public void setPets(List<Pet> pets) {
275	        this.pets = new HashSet<>(pets);
276	    }
277	
278	    public void addPet(Pet pet) {
279	        getPetsInternal().add(pet);
280	        pet.setOwner(this);
281	    }
282	
283	    /**
284	     * Return the Pet with the given name, or null if none found for this Owner.
285	     *
286	     * @param name to test
287	     * @return true if pet name is already in use
288	     */
289	    public Pet getPet(String name) {
290	        return getPet(name, false);
291	    }
292	
293	    /**
294	     * Return the Pet with the given name, or null if none found for this Owner.
295	     *
296	     * @param name to test
297	     * @return true if pet name is already in use
298	     */
299	    public Pet getPet(String name, boolean ignoreNew) {
300	        name = name.toLowerCase();
301	        for (Pet pet : getPetsInternal()) {
302	            if (!ignoreNew || !pet.isNew()) {
303	                String compName = pet.getName();
304	                compName = compName.toLowerCase();
305	                if (compName.equals(name)) {
306	                    return pet;
307	                }
308	            }
309	        }
310	        return null;
311	    }
312	
313	    public Pet getPet(Integer petId) {
314	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
315	    }
316	
317	    @Override
318	    public String toString() {
319	        return new ToStringCreator(this)
320	
321	            .append("id", this.getId())
322	            .append("new", this.isNew())
323	            .append("lastName", this.getLastName())
324	            .append("firstName", this.getFirstName())
325	            .append("address", this.address)
326	            .append("city", this.city)
327	            .append("telephone", this.telephone)
328	            .toString();
329	    }
330	}
